import itertools, math
from functools import lru_cache

def lis_len(seq):
    # O(n^2) patience-ish
    if not seq: return 0
    best = [1]*len(seq)
    for i in range(len(seq)):
        for j in range(i):
            if seq[j] < seq[i]:
                best[i] = max(best[i], best[j]+1)
    return max(best)

def lds_len(seq):
    return lis_len([-x for x in seq])

def rsk_shape(seq):
    rows = []
    for x in seq:
        placed = False
        for r in range(len(rows)):
            # find leftmost >= x
            for j in range(len(rows[r])):
                if rows[r][j] >= x:
                    rows[r][j] = x
                    placed = True
                    break
            if placed: break
        if not placed:
            rows.append([x])
    return tuple(len(r) for r in rows)

def brute(A, B):
    n = A*B - 1
    cnt = 0
    valid = []
    for p in itertools.permutations(range(1, n+1)):
        if lis_len(p) != A or lds_len(p) != B:
            continue
        ok = False
        for nn in range(1, n):  # n from 1 to AB-2 = n-1
            ext = p + (nn + 0.5,)
            if lis_len(ext) == A and lds_len(ext) == B:
                ok = True
                break
        if ok:
            cnt += 1
            valid.append(p)
    return cnt, valid

# shape check for (2,2)
cnt, valid = brute(2,2)
print("(2,2):", cnt, valid)
cnt, valid = brute(3,2)
print("(3,2):", cnt, valid)
# shapes of valid for (3,2)
shapes = set(rsk_shape(v) for v in valid)
print("shapes:", shapes)
cnt4, valid4 = brute(4,2)
print("(4,2):", cnt4)
print("shapes (4,2):", set(rsk_shape(v) for v in valid4))
