from functools import lru_cache

def count_good_dp(A, B):
    """Count SYT of shape lam=(A*(B-1), A-1) such that no intermediate
    shape in the growth chain has two consecutive rows of length A-1."""
    lam = [A]*(B-1) + [A-1]
    # DP over sub-partitions (nonincreasing tuple of length B, <= lam)
    from collections import defaultdict
    start = tuple([0]*B)
    dp = {start: 1}
    for step in range(sum(lam)):
        ndp = defaultdict(int)
        for mu, v in dp.items():
            # addable cells
            prev = 10**9
            for i in range(B):
                if mu[i] < lam[i] and (i == 0 or mu[i-1] > mu[i]):
                    nu = list(mu); nu[i] += 1
                    # constraint: no two consecutive rows == A-1
                    ok = True
                    for r in range(B-1):
                        if nu[r] == A-1 and nu[r+1] == A-1:
                            ok = False; break
                    if ok:
                        ndp[tuple(nu)] += v
                prev = mu[i]
        dp = ndp
    return dp[tuple(lam)]

