import itertools, math
from functools import lru_cache

def lis_len(seq):
    if not seq: return 0
    tails = []
    import bisect
    for x in seq:
        i = bisect.bisect_left(tails, x)
        if i == len(tails): tails.append(x)
        else: tails[i] = x
    return len(tails)

def lds_len(seq):
    # strictly decreasing = LIS of complement
    return lis_len([-x for x in seq])

def check(P, A, B):
    N = len(P)
    if lis_len(P) != A or lds_len(P) != B: return None
    # exists n in 1..N-1 with appending n+0.5 preserves LIS=A, LDS=B
    works = []
    for n in range(1, N):
        Q = P + [n + 0.5]
        l, d = lis_len(Q), lds_len(Q)
        if l == A and d == B:
            works.append(n)
    return works

def count_all(A, B, maxN=10):
    N = A*B - 1
    if N > maxN: return None
    cnt = 0
    total = 0
    details = []
    for P in itertools.permutations(range(1, N+1)):
        w = check(P, A, B)
        if w is not None:
            total += 1
            if w:
                cnt += 1
                details.append((P, w))
    return cnt, total, details[:8]

for (A,B) in [(2,2),(3,2),(2,3),(4,2),(2,4),(3,3),(4,3),(3,4)]:
    r = count_all(A,B)
    if r:
        cnt, total, det = r
        print(f"(A,B)=({A},{B}) N={A*B-1}: exists-reading count={cnt}, total(LIS=A,LDS=B)={total}, sample={det[:4]}")
